<?php require 'db.php';require 'helpers.php';require_student();$uid=(int)$_SESSION['user']['id'];$q=$pdo->prepare('SELECT u.name,u.email,s.mobile,s.enrollment_number,s.course FROM users u LEFT JOIN students s ON s.user_id=u.id WHERE u.id=?');$q->execute([$uid]);$profile=$q->fetch()?:[];$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$mobile=trim($_POST['mobile']??'');if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9+() -]{8,20}$/',$mobile)){$err='Please enter a valid name, email address, and mobile number.';}else{try{$pdo->beginTransaction();$s=$pdo->prepare('UPDATE users SET name=?,email=?,username=? WHERE id=?');$s->execute([$name,$email,$email,$uid]);$s=$pdo->prepare('UPDATE students SET name=?,email=?,mobile=? WHERE user_id=?');$s->execute([$name,$email,$mobile,$uid]);$pdo->commit();$_SESSION['user']['name']=$name;$_SESSION['user']['email']=$email;audit($pdo,'profile_update','Student updated profile');flash('Profile updated successfully.');header('Location: updateprofile.php');exit;}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$err='That email address may already be used by another account.';}}}page_header('Update Profile');if($err)echo '<div class="error">'.e($err).'</div>'; ?>
<div class="auth-layout"><section class="auth-aside"><span class="eyebrow">Your information</span><h1>Keep your profile up to date.</h1><p>Correct contact details help keep your student account and event registrations connected.</p><p>Enrollment number and course are managed as academic records.</p></section><section class="auth-card"><h2>Personal details</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label for="name">Full name</label><input id="name" name="name" required minlength="2" value="<?=e($profile['name']??'')?>"><label for="email">Email address</label><input id="email" type="email" name="email" required value="<?=e($profile['email']??'')?>"><label for="mobile">Mobile number</label><input id="mobile" name="mobile" required value="<?=e($profile['mobile']??'')?>"><label>Enrollment number</label><input value="<?=e($profile['enrollment_number']??'')?>" disabled><label>Course</label><input value="<?=e($profile['course']??'')?>" disabled><button type="submit">Save changes →</button></form></section></div><?php page_footer(); ?>